/* Kalu 4.0: assistente educativo local, sem API, sem coleta ou conexão externa. */
(function(){'use strict';
const KEY='kalu_settings_v4', LESSONS=Array.isArray(window.KALU_LESSONS)?window.KALU_LESSONS:[];
const MODE=location.pathname.endsWith('simulado.html')?'exam':location.pathname.endsWith('aulona.html')?'lessons':'home';
const defaults={enabled:true,proactive:true,voice:false,slogans:true,quietUntil:0,minimized:false};
let settings={...defaults};try{settings={...settings,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(settings))}catch{}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s??'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
const common=new Set('a o os as um uma uns umas de da do das dos em no na nos nas para por que qual quais como onde eu voce vocês me meu minha estou e ou com sem sobre ao aos é ser ter foi isso esse essa deste esta este aquele um pouco quero gostaria preciso poderia pode ajuda explicar explique entendi entendo melhor mais muito por favor teco kalu'.split(' '));
const words=s=>[...new Set(norm(s).split(' ').filter(w=>w.length>2&&!common.has(w)))];
const slogans=['Conhecimento se constrói coletivamente. Bora aprender mais um pouco?','O estudo é uma ferramenta de emancipação. Um passo de cada vez!','A solidariedade também cabe na sala de estudo: aprender e compartilhar.','Quem estuda o mundo também pode compreender como transformá-lo.','Paciência, organização e esforço coletivo: seguimos juntos!'];
let lastNudge=0,lastAction=Date.now(),nudgeCount=0,toastTimer=null,opened=false,shutForExam=false;
const el=id=>document.getElementById(id);
function examActive(){const e=el('exam');return MODE==='exam'&&e&&!e.classList.contains('hidden');}
function studyContext(){if(MODE!=='lessons')return null;try{if(typeof SLIDES!=='undefined'&&typeof current==='number'&&typeof screen==='string'&&screen==='slide'){const s=SLIDES[current];return s?{title:s.chapter,cat:s.cat,index:current,phase:s.phase,explain:s.explain,idea:s.idea,example:s.example,question:s.question,why:s.why}:null}}catch(e){}return null}
function latestRecord(){try{const a=JSON.parse(localStorage.getItem('tjsp_sim_2026_history_v1')||'[]');return Array.isArray(a)?a[a.length-1]:null}catch{return null}}
function latestWrong(){const r=latestRecord();if(!r)return null;let i=r.questions.findIndex((q,k)=>r.answers[k]!==q.answer);return i>=0?r.questions[i]:null}
function lessonLink(l){return 'aulona.html?slide='+encodeURIComponent(l.id)}
function lookup(query){const queryWords=words(query);if(!queryWords.length)return null;let best=null,bestScore=0;for(let l of LESSONS){const title=norm(l.title),cat=norm(l.cat),explain=norm(l.explain),idea=norm(l.idea);let score=0;for(const w of queryWords){if(title.split(' ').includes(w))score+=10;else if(title.includes(w))score+=5;if(cat.split(' ').includes(w))score+=2;if(explain.includes(w))score+=1;if(idea.includes(w))score+=1}if(score>bestScore){best=l;bestScore=score}}
return bestScore>=5?best:null}
function say(text,actions=[],info=''){if(!settings.enabled||examActive())return;el('kalu-answer').textContent=text;el('kalu-meta').textContent=info;const box=el('kalu-actions');box.replaceChildren();actions.forEach(a=>{if(a.href){const link=document.createElement('a');link.href=a.href;link.textContent=a.label;box.appendChild(link)}else if(a.fn){const b=document.createElement('button');b.type='button';b.textContent=a.label;b.addEventListener('click',a.fn);box.appendChild(b)}});opened=true;el('kalu-dialog').hidden=false;el('kalu-root').classList.remove('kalu-min');settings.minimized=false;save();if(settings.voice)speak(text)}
function speak(text){if(!settings.voice||examActive()||!('speechSynthesis'in window))return;try{speechSynthesis.cancel();const msg=new SpeechSynthesisUtterance(text.slice(0,340));msg.lang='pt-BR';msg.rate=1;msg.volume=.7;const voices=speechSynthesis.getVoices(),v=voices.find(v=>v.lang.toLowerCase()==='pt-br');if(v)msg.voice=v;speechSynthesis.speak(msg)}catch(e){}}
function reply(question){if(examActive()){return}let q=norm(question);if(!q){say('Me conta qual assunto ou dúvida você quer trabalhar.');return}
if(/(silencio|fica quieto|pausa|nao incomode|descansar|pare de falar)/.test(q)){settings.quietUntil=Date.now()+30*60000;save();say('Combinado! Vou ficar 30 minutos sem dar sugestões espontâneas. Se precisar, é só me chamar.');return}
if(/(o que voce faz|quem e voce|como funciona o kalu|o que e kalu)/.test(q)){say('Sou o Kalu, um ajudante de estudos local. Procuro assuntos nos 366 slides, dou exemplos já presentes no curso e sugiro aulas. Não sou uma IA generativa e posso não encontrar algumas respostas.',[{label:'Abrir a Aulona',href:'aulona.html'},{label:'Fazer simulado',href:'simulado.html'}]);return}
if(/(onde parei|continuar|voltar a estudar|proxima aula)/.test(q)){const idx=nextUnread();say('Vamos retomar o curso! Preparei um atalho para o próximo slide ainda não marcado como concluído.',[{label:'Continuar aula',href:'aulona.html?slide='+idx}]);return}
if(/(simulado|fazer prova|treinar questoes)/.test(q)){say('Podemos ir para o Simulado. Durante a prova, fico em silêncio para não interferir nas respostas.',[{label:'Abrir simulado',href:'simulado.html'}]);return}
if(/(desempenho|minha nota|meus erros|revisar erros)/.test(q)){let r=latestRecord();if(!r){say('Ainda não encontrei um simulado concluído neste navegador. Que tal fazer um treino?', [{label:'Abrir simulado',href:'simulado.html'}]);return}const wrong=latestWrong();let rec=wrong?lookup(wrong.stem+' '+wrong.cat):null;say('Seu último simulado teve '+r.score+' acertos de 70. '+(wrong?'Encontrei uma questão para revisar na disciplina de '+wrong.cat+'.':'Parabéns, sem erros nesse último registro!'),rec?[{label:'Revisar aula relacionada',href:lessonLink(rec)}]:[{label:'Painel de desempenho',href:'index.html'}]);return}
const context=studyContext();if(/(isso|essa aula|esse assunto|o slide|aqui|nao entendi)/.test(q)&&context){let ex=/exemplo|pratica|caso/.test(q)?context.example:context.explain;say(context.title+': '+(ex||context.idea||'Abra a explicação para ver o conteúdo.'),[{label:'Ver exemplo',fn:()=>say(context.example||'Não há exemplo disponível neste slide.',[{label:'Voltar à aula',href:'aulona.html?slide='+context.index}])}], 'Fonte: Aulona · slide '+(context.index+1));return}
const l=lookup(question);if(l){let wantExample=/exemplo|exemplifique|situacao|caso pratico/.test(q),wantSimple=/simples|facil|crianca/.test(q);let body=wantExample?(l.example||l.explain):wantSimple?(l.idea||l.explain):l.explain;say(l.title+': '+body,[{label:'Abrir aula · slide '+(l.id+1),href:lessonLink(l)},{label:'Ver exemplo',fn:()=>say(l.example||'Este assunto não tem exemplo disponível na base.',[{label:'Ir para a aula',href:lessonLink(l)}],'Fonte: Aulona · '+l.title)}],'Fonte: material local da Aulona · '+l.cat+'. Verifique a legislação vigente quando necessário.');return}
say('Não encontrei uma explicação confiável para essa pergunta nos nossos slides. Tente usar o nome do assunto (por exemplo, “crase”, “mandado de segurança” ou “Excel”). Não vou inventar uma resposta.',[{label:'Buscar nos slides',href:'aulona.html'}]);}
function nextUnread(){try{const st=JSON.parse(localStorage.getItem('teca_tjsp_mega_2026_v2')||'{}'),read=st.read||{};for(let i=0;i<366;i++)if(!read[i])return i}catch(e){}return 0}
function auto(text){if(!settings.enabled||!settings.proactive||Date.now()<settings.quietUntil||examActive())return;let now=Date.now();if(now-lastNudge<45000)return;lastNudge=now;nudgeCount++;const toast=el('kalu-toast');toast.innerHTML='';const span=document.createElement('span');span.textContent=text;let b=document.createElement('button');b.textContent='Conversar';b.onclick=()=>{toast.hidden=true;say(text,[{label:'Próxima aula',href:'aulona.html?slide='+nextUnread()},{label:'Rever erros',fn:()=>reply('revisar erros')}])};toast.append(span,b);toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{toast.hidden=true},12000)}
function onEvent(ev){const d=ev.detail||{};if(d.type==='exam-start'){shutForExam=true;settleExam();return}if(d.type==='exam-end'){shutForExam=false;settleExam();auto('Prova finalizada! Quando quiser, a gente pode revisar os erros juntos.');return}
if(d.type==='wrong'){auto('Essa questão foi complicada? Quer que eu explique o assunto sem pressa?');return}
if(d.type==='correct'){if(nudgeCount%3===0)auto('Boa! O aprendizado é construído passo a passo.');return}
if(d.type==='completed'){if(nudgeCount%3===0)auto('Mais uma etapa concluída. Conhecimento se constrói coletivamente!');return}
if(d.type==='slide'&&d.index%6===0)auto('Opa! '+d.title+'. Se ficar difícil, pode me perguntar.');}
function settleExam(){const root=el('kalu-root');if(!root)return;root.classList.toggle('kalu-rest',!!examActive());if(examActive()){el('kalu-dialog').hidden=true;el('kalu-toast').hidden=true;try{speechSynthesis.cancel()}catch(e){}}}
function build(){if(el('kalu-root'))return;
const root=document.createElement('section');root.id='kalu-root';root.setAttribute('aria-label','Kalu, assistente de estudos');
root.innerHTML='<div class="kalu-toast" id="kalu-toast" role="status" hidden></div><div class="kalu-stage"><div class="kalu-character"><button id="kalu-toggle" type="button" aria-label="Abrir ou minimizar Kalu"><img src="data:image/webp;base64," alt="Kalu, estrela vermelha com cabelo e barba brancos, segurando uma foice e um martelo"></button><div class="kalu-status">★ Kalu · assistente local</div></div><div class="kalu-bubble" id="kalu-dialog" role="region" aria-label="Conversa com Kalu" hidden><div class="kalu-head"><div><strong>Kalu</strong><br><small>Amigo e professor · respostas locais</small></div><div class="kalu-controls"><button type="button" id="kalu-preferences" title="Preferências" aria-label="Preferências">⚙</button><button type="button" id="kalu-minimize" title="Minimizar" aria-label="Minimizar">−</button><button type="button" id="kalu-close" title="Ocultar Kalu" aria-label="Ocultar Kalu">×</button></div></div><div class="kalu-text" id="kalu-answer" aria-live="polite">Oi! Sou o Kalu. Quer continuar uma aula, revisar erros ou tirar uma dúvida?</div><div class="kalu-meta" id="kalu-meta">Base de respostas: conteúdos do próprio curso. Não é uma IA generativa.</div><div class="kalu-actions" id="kalu-actions"><a href="aulona.html">📖 Abrir Aulona</a><a href="simulado.html">📝 Simulado</a></div><form id="kalu-form" class="kalu-inputrow"><input id="kalu-question" type="text" maxlength="240" placeholder="Pergunte sobre um assunto..." aria-label="Pergunta para Kalu"><button type="submit">Enviar</button></form><div class="kalu-settings" id="kalu-settings" hidden><label><input id="kalu-proactive" type="checkbox"> Sugestões proativas</label><label><input id="kalu-voice" type="checkbox"> Voz opcional (navegador)</label><label><input id="kalu-slogans" type="checkbox"> Frases motivacionais de inspiração comunista</label><button type="button" id="kalu-pause">Pausar sugestões por 30 min</button><button type="button" id="kalu-restart">Reativar sugestões</button><button type="button" id="kalu-disable">Ocultar o Kalu nesta sessão</button><small>Preferências ficam salvas no navegador. Nada é enviado a servidores pelo assistente.</small></div></div></div>';
// Nested button avoided: avatar image is the content of the button only
 document.body.appendChild(root);
 const toggle=()=>{if(examActive()){alert('O Kalu fica em silêncio durante a prova. Você pode consultar a ajuda ? para navegar.');return}if(el('kalu-dialog').hidden){root.classList.remove('kalu-min');el('kalu-dialog').hidden=false;opened=true}else{root.classList.add('kalu-min');el('kalu-dialog').hidden=true;settings.minimized=true;save()}};
 el('kalu-toggle').onclick=toggle;el('kalu-minimize').onclick=()=>{el('kalu-dialog').hidden=true;root.classList.add('kalu-min');settings.minimized=true;save()};el('kalu-close').onclick=()=>{root.classList.add('kalu-hidden');settings.enabled=false;save()};
 el('kalu-form').onsubmit=e=>{e.preventDefault();const question=el('kalu-question').value.trim();if(!question)return;el('kalu-question').value='';reply(question)};
 el('kalu-preferences').onclick=()=>{el('kalu-settings').hidden=!el('kalu-settings').hidden};
 el('kalu-proactive').checked=settings.proactive;el('kalu-voice').checked=settings.voice;el('kalu-slogans').checked=settings.slogans;
 el('kalu-proactive').onchange=e=>{settings.proactive=e.target.checked;save()};el('kalu-voice').onchange=e=>{settings.voice=e.target.checked;if(!settings.voice&&'speechSynthesis'in window)speechSynthesis.cancel();save()};el('kalu-slogans').onchange=e=>{settings.slogans=e.target.checked;save()};
 el('kalu-pause').onclick=()=>{settings.quietUntil=Date.now()+30*60000;save();say('Combinado, 30 minutos sem sugestões espontâneas. Pode continuar no seu ritmo.')};
 el('kalu-restart').onclick=()=>{settings.quietUntil=0;save();say('Voltei! Vou dar dicas ao longo dos estudos, sem tirar você da aula.')};
 el('kalu-disable').onclick=()=>{settings.enabled=false;save();root.classList.add('kalu-hidden')};
 if(!settings.enabled)root.classList.add('kalu-hidden');if(settings.minimized)root.classList.add('kalu-min');
 const anchor=document.createElement('button');anchor.type='button';anchor.textContent='★ Kalu';anchor.id='kalu-return';anchor.style.cssText='position:fixed;right:12px;top:12px;z-index:135;background:#1b3744;color:#defbee;border:1px solid #81beb5;border-radius:999px;padding:7px 12px;font:600 12px system-ui;cursor:pointer';anchor.title='Mostrar Kalu';anchor.onclick=()=>{settings.enabled=true;save();root.classList.remove('kalu-hidden','kalu-min');el('kalu-dialog').hidden=false};document.body.appendChild(anchor);
 const updateAnchor=()=>{anchor.hidden=settings.enabled||examActive()};updateAnchor();new MutationObserver(updateAnchor).observe(root,{attributes:true,attributeFilter:['class']});
 window.addEventListener('kalu:event',onEvent);
 ['pointerdown','keydown','wheel','scroll'].forEach(name=>document.addEventListener(name,()=>{lastAction=Date.now()},{passive:true}));
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible'){try{speechSynthesis.cancel()}catch(e){}}});
 setInterval(()=>{settleExam();if(document.visibilityState!=='visible'||examActive()||!settings.enabled||!settings.proactive||Date.now()<settings.quietUntil)return;if(Date.now()-lastAction>150000&&Date.now()-lastNudge>150000){auto('Tá tudo bem por aí? Se quiser, posso sugerir uma pausa ou uma revisão curtinha.');lastAction=Date.now()}else if(Date.now()-lastNudge>210000){const c=studyContext();if(c)auto('Como está indo '+c.title+'? Posso explicar ou mostrar um exemplo.');else if(settings.slogans)auto(slogans[Math.floor(Math.random()*slogans.length)]);else auto('Pronto para uma próxima atividade? Posso ajudar.')}},20000);
 // Welcome only after DOM is stable; use a subtle toast rather than covering lesson contents
 setTimeout(()=>{settleExam();if(MODE==='home')auto('Opa, camarada! Eu sou o Kalu. Quer continuar os estudos ou revisar os erros?')},1600);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',build);else build();
})();
